INSERT INTO public.flashcards
  (id1, cn, pinyin, vocabulary, pinyin_vocab, th, sentence_test, translate, pinyin_sentence)
VALUES
(901, '速', 'sù', '速度', 'sù dù', 'ความเร็ว', '我想以最快的速度把花送给妈妈。', 'ฉันอยากเอาดอกไม้ไปให้แม่ด้วยความเร็วที่สุด', 'wǒ xiǎng yǐ zuì kuài de sù dù bǎ huā sòng gěi mā mā'),
(902, '度', 'dù', '温度', 'wēn dù', 'อุณหภูมิ', '屋子里温度太低了，打开电暖气吧！', 'ในห้องอุณหภูมิต่ำเกินไป เปิดฮีตเตอร์เถอะ!', 'wū zi lǐ wēn dù tài dī le, dǎ kāi diàn nuǎn qì ba'),
(903, '铅', 'qiān', '铅笔', 'qiān bǐ', 'ดินสอ', '他用铅笔勾画出了那个人的外貌。', 'เขาใช้ดินสอร่างรูปหน้าตาของคนคนนั้น', 'tā yòng qiān bǐ gōu huà chū le nà gè rén de wài mào'),
(904, '灰', 'huī', '灰色', 'huī sè', 'สีเทา', '阴天的时候，天空是灰色的。', 'ตอนฟ้าครึ้ม ท้องฟ้าเป็นสีเทา', 'yīn tiān de shí hòu, tiān kōng shì huī sè de'),
(905, '亿', 'yì', '亿万', 'yì wàn', 'ร้อยล้าน/มหาศาล', '亿万观众都在关注世界杯足球比赛。', 'ผู้ชมนับร้อยล้านต่างจับตาดูการแข่งฟุตบอลโลก', 'yì wàn guān zhòng dōu zài guān zhù shì jiè bēi zú qiú bǐ sài'),
(906, '已', 'yǐ', '已经', 'yǐ jīng', 'แล้ว/เรียบร้อยแล้ว', '这个小木马已经坏了，不能玩了。', 'ม้าไม้ตัวนี้พังไปแล้ว เล่นไม่ได้แล้ว', 'zhè ge xiǎo mù mǎ yǐ jīng huài le, bù néng wán le'),
(907, '巨', 'jù', '巨大', 'jù dà', 'ใหญ่โต/มหึมา', '山顶突然落下一块巨大的石头。', 'ยอดเขาจู่ๆ ก็มีก้อนหินใหญ่มหึมาตกลงมา', 'shān dǐng tū rán luò xià yí kuài jù dà de shí tou'),
(908, '检', 'jiǎn', '检查', 'jiǎn chá', 'ตรวจสอบ', '园丁在检查大树有没有生虫子。', 'คนสวนกำลังตรวจดูว่าต้นไม้ใหญ่มีหนอนไหม', 'yuán dīng zài jiǎn chá dà shù yǒu méi yǒu shēng chóng zi'),
(909, '蚜', 'yá', '蚜虫', 'yá chóng', 'เพลี้ยอ่อน', '蚜虫是一种会破坏植物的害虫。', 'เพลี้ยอ่อนเป็นแมลงศัตรูพืชชนิดหนึ่งที่ทำลายต้นไม้', 'yá chóng shì yì zhǒng huì pò huài zhí wù de hài chóng'),
(910, '经', 'jīng', '经过', 'jīng guò', 'ผ่าน/เหตุการณ์ที่ผ่านมา', '他慢慢地告诉了我事情的经过。', 'เขาค่อยๆ เล่าเหตุการณ์ที่เกิดขึ้นให้ฉันฟัง', 'tā màn màn de gào su le wǒ shì qíng de jīng guò'),
(911, '驶', 'shǐ', '驾驶', 'jià shǐ', 'ขับขี่', '遇到雨雪天气要小心驾驶。', 'เจออากาศฝนตกหิมะตกต้องขับขี่อย่างระมัดระวัง', 'yù dào yǔ xuě tiān qì yào xiǎo xīn jià shǐ'),
(912, '绝', 'jué', '绝招', 'jué zhāo', 'ไม้เด็ด/เคล็ดลับพิเศษ', '师父把做菜的绝招传给了弟子。', 'อาจารย์ถ่ายทอดไม้เด็ดการทำอาหารให้ลูกศิษย์', 'shī fu bǎ zuò cài de jué zhāo chuán gěi le dì zǐ'),
(913, '引', 'yǐn', '吸引', 'xī yǐn', 'ดึงดูด', '这里的景色吸引了成千上万的游客。', 'ทิวทัศน์ที่นี่ดึงดูดนักท่องเที่ยวนับหมื่นนับพัน', 'zhè lǐ de jǐng sè xī yǐn le chéng qiān shàng wàn de yóu kè'),
(914, '亚', 'yà', '亚军', 'yà jūn', 'รองชนะเลิศ (ที่สอง)', '小朋友在跑步比赛中得了亚军。', 'เด็กน้อยได้รางวัลรองชนะเลิศในการแข่งวิ่ง', 'xiǎo péng yǒu zài pǎo bù bǐ sài zhōng dé le yà jūn'),
(915, '吾', 'wú', '吾辈', 'wú bèi', 'พวกเรา (ภาษาโบราณ)', '吾就是我，吾辈就是我们的同龄人。', 'อู๋คือฉัน อู๋เป้ยก็คือคนรุ่นเดียวกับเรา', 'wú jiù shì wǒ, wú bèi jiù shì wǒ men de tóng líng rén'),
(916, '忠', 'zhōng', '忠心', 'zhōng xīn', 'ความจงรักภักดี', '他对祖国的一片忠心得到了回报。', 'ความจงรักภักดีต่อมาตุภูมิของเขาได้รับการตอบแทน', 'tā duì zǔ guó de yí piàn zhōng xīn dé dào le huí bào'),
(917, '环', 'huán', '耳环', 'ěr huán', 'ต่างหู', '这对耳环很特别，是姐姐最喜欢的。', 'ต่างหูคู่นี้พิเศษมาก เป็นคู่ที่พี่สาวชอบที่สุด', 'zhè duì ěr huán hěn tè bié, shì jiě jie zuì xǐ huān de'),
(918, '技', 'jì', '杂技', 'zá jì', 'กายกรรม', '昨天看的那场杂技表演太精彩了。', 'การแสดงกายกรรมที่ดูเมื่อวานสุดยอดมาก', 'zuó tiān kàn de nà chǎng zá jì biǎo yǎn tài jīng cǎi le'),
(919, '保', 'bǎo', '保护', 'bǎo hù', 'ปกป้อง/คุ้มครอง', '我们要保护野生动物。', 'เราต้องปกป้องสัตว์ป่า', 'wǒ men yào bǎo hù yě shēng dòng wù'),
(920, '术', 'shù', '美术', 'měi shù', 'ศิลปะ', '小朋友的美术作品得了第一名。', 'ผลงานศิลปะของเด็กน้อยได้รางวัลที่หนึ่ง', 'xiǎo péng yǒu de měi shù zuò pǐn dé le dì yī míng'),
(921, '敌', 'dí', '敌人', 'dí rén', 'ศัตรู', '战士们把敌人打得落花流水。', 'เหล่านักรบตีศัตรูจนแตกพ่ายยับเยิน', 'zhàn shì men bǎ dí rén dǎ de luò huā liú shuǐ'),
(922, '寻', 'xún', '寻找', 'xún zhǎo', 'ค้นหา', '为了治好病，他们四处寻找名医。', 'เพื่อรักษาโรคให้หาย พวกเขาออกตามหาหมอชื่อดังไปทั่ว', 'wèi le zhì hǎo bìng, tā men sì chù xún zhǎo míng yī'),
(923, '消', 'xiāo', '消失', 'xiāo shī', 'หายไป/สูญหาย', '小猴子发现水里的月亮消失了。', 'ลิงน้อยพบว่าพระจันทร์ในน้ำหายไปแล้ว', 'xiǎo hóu zi fā xiàn shuǐ lǐ de yuè liàng xiāo shī le'),
(924, '志', 'zhì', '斗志', 'dòu zhì', 'ขวัญกำลังใจในการต่อสู้', '雄壮的歌声激起了战士们的斗志。', 'เสียงเพลงอันฮึกเหิมปลุกขวัญกำลังใจของเหล่านักรบ', 'xióng zhuàng de gē shēng jī qǐ le zhàn shì men de dòu zhì'),
(925, '夺', 'duó', '抢夺', 'qiǎng duó', 'แย่งชิง/ปล้น', '敌人冲进城里四处抢夺东西。', 'ศัตรูบุกเข้าเมืองแล้วปล้นข้าวของไปทั่ว', 'dí rén chōng jìn chéng lǐ sì chù qiǎng duó dōng xi'),
(926, '于', 'yú', '终于', 'zhōng yú', 'ในที่สุด', '终于干完活了，可以休息一下啦！', 'ในที่สุดก็ทำงานเสร็จ พักได้สักหน่อยแล้ว!', 'zhōng yú gàn wán huó le, kě yǐ xiū xi yí xià la'),
(927, '终', 'zhōng', '终点', 'zhōng diǎn', 'เส้นชัย/จุดหมาย', '参赛的队员接二连三地冲过了终点。', 'นักกีฬาที่ลงแข่งพุ่งเข้าเส้นชัยติดๆ กันทีละคน', 'cān sài de duì yuán jiē èr lián sān de chōng guò le zhōng diǎn'),
(928, '凤', 'fèng', '凤凰', 'fèng huáng', 'หงส์ (ฟีนิกซ์)', '龙和凤凰都是中国神话里的动物。', 'มังกรและหงส์ล้วนเป็นสัตว์ในเทพนิยายจีน', 'lóng hé fèng huáng dōu shì zhōng guó shén huà lǐ de dòng wù'),
(929, '凰', 'huáng', '凤凰', 'fèng huáng', 'หงส์ (ฟีนิกซ์)', '凤凰是百鸟之王，能带来好运气。', 'หงส์เป็นราชาแห่งมวลนก นำโชคดีมาให้', 'fèng huáng shì bǎi niǎo zhī wáng, néng dài lái hǎo yùn qì'),
(930, '禅', 'chán', '坐禅', 'zuò chán', 'นั่งสมาธิ (เซน)', '长老正双手合十在禅房里坐禅。', 'หลวงปู่กำลังพนมมือนั่งสมาธิอยู่ในห้องเซน', 'zhǎng lǎo zhèng shuāng shǒu hé shí zài chán fáng lǐ zuò chán'),
(931, '隐', 'yǐn', '隐藏', 'yǐn cáng', 'ซ่อนเร้น', '小兔子没注意到隐藏在草丛中的狼。', 'กระต่ายน้อยไม่ทันสังเกตหมาป่าที่ซ่อนอยู่ในพงหญ้า', 'xiǎo tù zi méi zhù yì dào yǐn cáng zài cǎo cóng zhōng de láng'),
(932, '使', 'shǐ', '使用', 'shǐ yòng', 'ใช้ (งาน)', '爷爷学会使用手机了，很有成就感。', 'คุณปู่ใช้มือถือเป็นแล้ว รู้สึกภูมิใจมาก', 'yé ye xué huì shǐ yòng shǒu jī le, hěn yǒu chéng jiù gǎn'),
(933, '纺', 'fǎng', '纺线', 'fǎng xiàn', 'ปั่นด้าย', '这位阿姨是个出了名的纺线高手。', 'คุณป้าคนนี้เป็นเซียนปั่นด้ายที่มีชื่อเสียง', 'zhè wèi ā yí shì gè chū le míng de fǎng xiàn gāo shǒu'),
(934, '织', 'zhī', '纺织', 'fǎng zhī', 'ทอผ้า/สิ่งทอ', '纺织是一门工艺，也是一门艺术。', 'การทอผ้าเป็นทั้งงานฝีมือและงานศิลปะ', 'fǎng zhī shì yì mén gōng yì, yě shì yì mén yì shù'),
(935, '披', 'pī', '披着', 'pī zhe', 'ห่มคลุม', '坏人装好人，就像披着羊皮的狼。', 'คนชั่วแกล้งเป็นคนดี เหมือนหมาป่าในคราบแกะ', 'huài rén zhuāng hǎo rén, jiù xiàng pī zhe yáng pí de láng'),
(936, '灵', 'líng', '精灵', 'jīng líng', 'ภูต/เอลฟ์', '跳动的小火苗好像一个舞动的精灵。', 'เปลวไฟน้อยที่กระพือเหมือนภูตที่กำลังร่ายรำ', 'tiào dòng de xiǎo huǒ miáo hǎo xiàng yí gè wǔ dòng de jīng líng'),
(937, '仍', 'réng', '仍然', 'réng rán', 'ยังคง', '奶奶八十多岁了，走路仍然很轻快。', 'คุณย่าอายุแปดสิบกว่าแล้ว เดินยังคล่องแคล่วอยู่เลย', 'nǎi nai bā shí duō suì le, zǒu lù réng rán hěn qīng kuài'),
(938, '池', 'chí', '池塘', 'chí táng', 'สระน้ำ/บ่อน้ำ', '夏天，池塘里开满了美丽的荷花。', 'ฤดูร้อน สระน้ำเต็มไปด้วยดอกบัวที่งดงาม', 'xià tiān, chí táng lǐ kāi mǎn le měi lì de hé huā'),
(939, '吞', 'tūn', '吞下', 'tūn xià', 'กลืน', '我现在饿得能一口吞下一头牛。', 'ตอนนี้ฉันหิวจนกินวัวได้ทั้งตัวในคำเดียว', 'wǒ xiàn zài è de néng yì kǒu tūn xià yì tóu niú'),
(940, '而', 'ér', '而且', 'ér qiě', 'อีกทั้ง/และยัง', '爷爷的胡子不但很多，而且很长。', 'หนวดของคุณปู่ไม่เพียงแต่ดกเยอะ แถมยังยาวอีกด้วย', 'yé ye de hú zi bú dàn hěn duō, ér qiě hěn cháng'),
(941, '际', 'jì', '边际', 'biān jì', 'ขอบเขต/สุดขอบ', '马儿在无边无际的草原上奔跑。', 'ม้าควบวิ่งอยู่บนทุ่งหญ้าอันกว้างสุดลูกหูลูกตา', 'mǎ ér zài wú biān wú jì de cǎo yuán shàng bēn pǎo'),
(942, '管', 'guǎn', '管子', 'guǎn zi', 'ท่อ/หลอด', '房子旁边有两根竹子做的管子。', 'ข้างบ้านมีท่อไม้ไผ่สองอัน', 'fáng zi páng biān yǒu liǎng gēn zhú zi zuò de guǎn zi'),
(943, '规', 'guī', '规矩', 'guī ju', 'กฎระเบียบ/กติกา', '要学会讲规矩，按规矩办事。', 'ต้องเรียนรู้ที่จะมีกติกา และทำตามกติกา', 'yào xué huì jiǎng guī ju, àn guī ju bàn shì'),
(944, '府', 'fǔ', '官府', 'guān fǔ', 'ที่ว่าการ/สำนักราชการ (สมัยก่อน)', '这个院子本来是古代的一处官府。', 'ลานบ้านแห่งนี้แต่เดิมเป็นที่ว่าการสมัยโบราณ', 'zhè ge yuàn zi běn lái shì gǔ dài de yí chù guān fǔ'),
(945, '议', 'yì', '抗议', 'kàng yì', 'ประท้วง/คัดค้าน', '人们对不公正的结果表示抗议。', 'ผู้คนแสดงการประท้วงต่อผลลัพธ์ที่ไม่ยุติธรรม', 'rén men duì bù gōng zhèng de jié guǒ biǎo shì kàng yì'),
(946, '莲', 'lián', '莲花', 'lián huā', 'ดอกบัว', '细雨过后，池里的莲花格外美丽。', 'หลังฝนปรอยผ่านไป ดอกบัวในสระงดงามเป็นพิเศษ', 'xì yǔ guò hòu, chí lǐ de lián huā gé wài měi lì'),
(947, '宽', 'kuān', '宽敞', 'kuān chǎng', 'กว้างขวางโล่งสบาย', '我们的教室干净整洁，宽敞明亮。', 'ห้องเรียนของเราสะอาดเป็นระเบียบ กว้างขวางสว่างไสว', 'wǒ men de jiào shì gān jìng zhěng jié, kuān chǎng míng liàng'),
(948, '级', 'jí', '级别', 'jí bié', 'ระดับ', '风力的大小共分为十八个级别。', 'ความแรงของลมแบ่งออกเป็นสิบแปดระดับ', 'fēng lì de dà xiǎo gòng fēn wéi shí bā gè jí bié'),
(949, '之', 'zhī', '之间', 'zhī jiān', 'ระหว่าง', '同学之间要团结友爱，互相帮助。', 'ระหว่างเพื่อนร่วมชั้นต้องรักสามัคคี ช่วยเหลือกัน', 'tóng xué zhī jiān yào tuán jié yǒu ài, hù xiāng bāng zhù'),
(950, '列', 'liè', '列队', 'liè duì', 'เข้าแถว', '运动会上，运动员列队走过主席台。', 'ในงานกีฬา นักกีฬาเดินเข้าแถวผ่านหน้าอัฒจันทร์ประธาน', 'yùn dòng huì shàng, yùn dòng yuán liè duì zǒu guò zhǔ xí tái');
